-- One row per Discord forum thread that has been (or is being) turned into a Linear issue.
CREATE TABLE issue_mappings (
  discord_thread_id          TEXT PRIMARY KEY,
  discord_guild_id           TEXT NOT NULL,
  discord_forum_channel_id   TEXT NOT NULL,
  discord_initial_message_id TEXT NOT NULL,
  discord_author_id          TEXT,

  -- Generated by us before calling issueCreate and passed as the issue id,
  -- so a retried create can never produce a second issue.
  linear_issue_id            TEXT NOT NULL UNIQUE,
  linear_issue_identifier    TEXT,
  linear_issue_url           TEXT,

  -- Intake: 'pending' -> 'created'; 'failed' after max attempts.
  status                     TEXT NOT NULL DEFAULT 'pending',
  intake_attempts            INTEGER NOT NULL DEFAULT 0,
  next_attempt_at            INTEGER NOT NULL DEFAULT 0,
  last_error                 TEXT,
  failure_notice_posted      INTEGER NOT NULL DEFAULT 0,
  link_attached              INTEGER NOT NULL DEFAULT 0,
  thread_renamed             INTEGER NOT NULL DEFAULT 0,
  ack_message_id             TEXT,

  -- Linear -> Discord sync.
  needs_sync                 INTEGER NOT NULL DEFAULT 0,
  sync_attempts              INTEGER NOT NULL DEFAULT 0,
  synced_label_ids           TEXT,
  last_state_id              TEXT,     -- last Linear state seen by sync (notifications fire on change)
  completed_at               INTEGER,
  archived_at                INTEGER,
  discord_deleted_at         INTEGER,
  linear_deleted_at          INTEGER,

  created_at                 INTEGER NOT NULL,
  updated_at                 INTEGER NOT NULL
);

CREATE INDEX idx_mappings_intake ON issue_mappings (status, next_attempt_at);
CREATE INDEX idx_mappings_needs_sync ON issue_mappings (needs_sync) WHERE needs_sync = 1;
CREATE INDEX idx_mappings_archive ON issue_mappings (completed_at) WHERE completed_at IS NOT NULL AND archived_at IS NULL;

-- Webhook deliveries already handled (Linear-Delivery header). Pruned after 7 days.
CREATE TABLE processed_events (
  event_id     TEXT PRIMARY KEY,
  source       TEXT NOT NULL,
  processed_at INTEGER NOT NULL
);
